DELETE FROM pending_payments;
DELETE FROM recurring_payments;
DELETE FROM transactions;
DELETE FROM payees;
DELETE FROM accounts;
DELETE FROM _counters;
UPDATE transactions
SET memo = CASE counterparty
      WHEN 'Payroll' THEN 'Employment or consulting income reconciliation; verify taxable-income classification and pay period; posted ' || substr(posted_at,1,10)
      WHEN 'Rent Portal' THEN 'Housing payment or portal adjustment; reconcile lease month, amount, and payment status; posted ' || substr(posted_at,1,10)
      WHEN 'Protected Reserve Interest' THEN CASE WHEN amount_minor = 0 THEN 'Estate reserve balance review only; no cash posted; reviewed ' || substr(posted_at,1,10) ELSE 'Estate reserve interest credit; reserve remains restricted; posted ' || substr(posted_at,1,10) END
      WHEN 'Transit' THEN 'Ordinary transit expense; household cash lane; posted ' || substr(posted_at,1,10)
      WHEN 'Utility Autopay' THEN 'Household utility autopay; ordinary cash lane; posted ' || substr(posted_at,1,10)
      WHEN 'Insurance Carrier' THEN 'Insurance premium or carrier adjustment; not an inherited-IRA distribution; posted ' || substr(posted_at,1,10)
      WHEN 'Medical Billing Office' THEN 'Medical invoice or patient-responsibility payment; retain invoice support; posted ' || substr(posted_at,1,10)
      WHEN 'Inherited IRA Custodian' THEN 'Custodian fee or beneficiary-account service charge; verify account and statement; posted ' || substr(posted_at,1,10)
      WHEN 'IRS Direct Pay' THEN 'Federal estimated-tax payment or refund adjustment; verify tax period; posted ' || substr(posted_at,1,10)
      WHEN 'Home Loan Servicing' THEN 'Mortgage servicing payment or adjustment; ordinary household obligation; posted ' || substr(posted_at,1,10)
      WHEN 'Auto Finance Center' THEN 'Auto-loan payment or correction; verify scheduled amount; posted ' || substr(posted_at,1,10)
      WHEN 'Card Issuer Autopay' THEN 'Credit-card autopay or returned-payment adjustment; verify statement and payment status; posted ' || substr(posted_at,1,10)
      WHEN 'Brokerage ACH' THEN 'Household brokerage cash transfer; separate from inherited-IRA account; posted ' || substr(posted_at,1,10)
      WHEN 'Grocery Co-op' THEN 'Ordinary grocery purchase; household cash lane; posted ' || substr(posted_at,1,10)
      WHEN 'Pharmacy' THEN 'Prescription or pharmacy purchase; medical cash lane; posted ' || substr(posted_at,1,10)
      ELSE 'Ordinary household transaction; verify purpose, account, and source document; posted ' || substr(posted_at,1,10)
    END;

UPDATE pending_payments
SET memo = CASE payee_id
      WHEN 'payee_mortgage' THEN 'Scheduled mortgage payment; confirm due date and available ordinary cash.'
      WHEN 'payee_auto' THEN 'Scheduled auto-loan payment; confirm statement and ordinary-cash coverage.'
      WHEN 'payee_student' THEN 'Custodian service payment pending; verify invoice and beneficiary account before release.'
      WHEN 'payee_hsa' THEN 'Health account contribution pending; verify eligibility and annual limit before release.'
      WHEN 'payee_brokerage' THEN 'Household brokerage transfer pending; do not treat as inherited-IRA activity.'
      ELSE 'Housing payment pending; verify due date, amount, and payment source.'
    END;

